+                            context = Comment;
+                        } else if (r.matchConsume("?")) {
+                            subset.append('?');
+                            context = ProcessingInstruction;
+                        }
+                    }
+                    break;
+                case '-':
+                    subset.append(c);
+                    if (context == Comment && r.matchConsume("->")) {
+                        subset.append("->");
+                        context = None;
+                    }
+                    break;
+                case '?':
+                    subset.append(c);
+                    if (context == ProcessingInstruction && r.matches('>')) {
+                        r.advance();
+                        subset.append('>');
+                        context = None;
+                    }
+                    break;
+                case ']':
+                    if (context == None) {
+                        String ws = r.consumeMatching(StringUtil::isWhitespace);
+                        if (r.matches('>')) {
+                            r.advance();
+                            t.emitDoctypePending();
+                            t.transition(Data);
+                            return;
+                        }
+                        subset.append(c);
+                        subset.append(ws);
+                        break;
+                    }
+                    subset.append(c);
+                    break;
+                case nullChar:
+                    t.error(current);
+                    subset.append(replacementChar);
+                    break;
+                case eof:
+                    t.eofError(current);
+                    t.emitDoctypePending();
+                    t.transition(Data);
+                    return;
+                default:
+                    subset.append(c);
+                    break;
+            }
