+package org.jsoup.integration;
+
+import org.jsoup.Jsoup;
+import org.jsoup.helper.HttpClientExecutorTest;
+import org.jsoup.nodes.Document;
+import org.junit.jupiter.api.AfterAll;
+import org.junit.jupiter.api.BeforeAll;
+import org.junit.jupiter.api.Test;
+
+import java.io.IOException;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+/**
+ Checks that repeated independent requests via the HttpClient reuse threads, rather than each starting a new
+ HttpClient with its own selector manager thread and worker pool.
+ */
+public class HttpClientThreadTest {
+    @BeforeAll
+    static void setUp() {
+        TestServer.start();
+        HttpClientExecutorTest.enableHttpClient();
+    }
+
+    @AfterAll
+    static void reset() {
+        HttpClientExecutorTest.disableHttpClient();
+    }
+
+    static long selectorThreads() {
+        return Thread.getAllStackTraces().keySet().stream()
+            .filter(t -> t.isAlive() && t.getName().endsWith("SelectorManager"))
+            .count();
+    }
+
+    @Test void repeatedRequestsDoNotSpawnClientThreads() throws IOException {
+        String url = TestServer.origin().echo.url();
+        Jsoup.connect(url).get(); // warm up the shared client
+        long before = selectorThreads();
+
+        int requests = 25;
+        for (int i = 0; i < requests; i++) {
+            Document doc = Jsoup.connect(url).data("requestNum", String.valueOf(i)).get();
+            assertEquals(String.valueOf(i), ConnectTest.ihVal("requestNum", doc));
+        }
+
+        long after = selectorThreads();
+        assertTrue(after - before <= 0,
+            "Expected no new HttpClient selector threads after " + requests + " requests, but went from " + before + " to " + after);
+    }
+}

