@@ -0,0 +1,51 @@
+package org.jsoup.internal;
+
+import org.junit.jupiter.api.Test;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+public class NormalizerTest {
+
+    @Test void normalizeOnlyTrimsAsciiWhitespaceAndFoldsAscii() {
+        assertEquals("data-x", Normalizer.normalize(" \t\n\f\rDATA-X \r\n"));
+        assertEquals("data-x\u0001", Normalizer.normalize("Data-X\u0001"));
+        assertNotEquals(Normalizer.normalize("data-x"), Normalizer.normalize("data-x\u0001"));
+        assertEquals("\u0001x", Normalizer.normalize("\u0001X"));
+        assertEquals("K", Normalizer.normalize("K")); // Kelvin sign is not folded to k
+        assertEquals("ſ", Normalizer.normalize("ſ")); // long s
+        assertEquals("İ", Normalizer.normalize("İ")); // dotted capital I
+        assertEquals("", Normalizer.normalize(null));
+    }
+
+    @Test void asciiLowerCase() {
+        assertEquals("abc-xyz09", Normalizer.asciiLowerCase("AbC-XyZ09"));
+        assertEquals("Ä", Normalizer.asciiLowerCase("Ä"));
+        String lower = "already";
+        assertSame(lower, Normalizer.asciiLowerCase(lower));
+        assertEquals("", Normalizer.asciiLowerCase(null));
+    }
+
+    @Test void trimAsciiWhitespace() {
+        assertEquals("a b", Normalizer.trimAsciiWhitespace(" \ta b\n"));
+        assertEquals("\u0001a\u0002", Normalizer.trimAsciiWhitespace(" \u0001a\u0002 "));
+        assertEquals("\u000Ba", Normalizer.trimAsciiWhitespace("\u000Ba")); // vertical tab is not HTML whitespace
+        assertEquals("", Normalizer.trimAsciiWhitespace("  "));
+    }
+
+    @Test void asciiEqualsIgnoreCase() {
+        assertTrue(Normalizer.asciiEqualsIgnoreCase("Data-X", "data-x"));
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("data-x\u0001", "data-x"));
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("K", "k"));
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("ſ", "s"));
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("ı", "i")); // dotless i
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("a", "ab"));
+        assertTrue(Normalizer.asciiEqualsIgnoreCase(null, null));
+        assertFalse(Normalizer.asciiEqualsIgnoreCase("a", null));
+    }
+
+    @Test void asciiRegionMatchesIgnoreCase() {
+        assertTrue(Normalizer.asciiRegionMatchesIgnoreCase("SCRIPT", 0, "scr", 0, 3));
+        assertFalse(Normalizer.asciiRegionMatchesIgnoreCase("SCRIPT", 0, "ſcr", 0, 3));
+        assertFalse(Normalizer.asciiRegionMatchesIgnoreCase("ab", 1, "bc", 0, 2)); // out of bounds
+    }
+}
