+
+/**
+ Tag and attribute names are ASCII case-insensitive in HTML: only A-Z fold, and only ASCII whitespace is trimmed.
+ Control characters and non-ASCII characters must not be dropped or folded into ASCII names.
+ */
+public class AsciiNameFoldingTest {
+    private static final String Kelvin = "K"; // lower-cases to 'k' under Unicode rules
+    private static final String LongS = "ſ";  // upper-cases to 'S' under Unicode rules
+    private static final String DotlessI = "ı"; // upper-cases to 'I' under Unicode rules
+
+    @Test void controlCharAttributeNameIsDistinctOnceAccepted() {
+        // names via the API keep control chars, and must not match the ASCII name
+        Document doc = Jsoup.parse("<div data-x=2></div>");
+        Element div = doc.expectFirst("div");
+        div.attributes().put("data-x\u0001", "1");
+        assertEquals(2, div.attributesSize());
+        assertEquals("1", div.attr("data-x\u0001"));
