@@ -0,0 +1,136 @@
+package org.jsoup.parser;
+
+import org.jsoup.Jsoup;
+import org.jsoup.TextUtil;
+import org.jsoup.nodes.Document;
+import org.jsoup.nodes.Element;
+import org.jsoup.nodes.Node;
+import org.junit.jupiter.api.Test;
+
+import java.util.List;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+/**
+ Tests that select, option, and optgroup content is parsed through the in body insertion mode, per the current HTML
+ Standard (which retired the "in select" and "in select in table" insertion modes).
+ */
+public class SelectParsingTest {
+
+    private static String body(String html) {
+        return TextUtil.stripNewlines(Jsoup.parse(html).body().html());
+    }
+
+    private static int errorCount(String html) {
+        Parser parser = Parser.htmlParser().setTrackErrors(10);
+        parser.parseInput(html, "");
+        return parser.getErrors().size();
+    }
+
+    @Test void customizableSelectContentIsKept() {
+        String html = "<select><button><selectedcontent></selectedcontent></button>" +
+            "<option><img src=x.png><span>One</span></option><div><option>Two</option></div></select>";
+        assertEquals("<select><button><selectedcontent></selectedcontent></button>" +
+            "<option><img src=\"x.png\"><span>One</span></option><div><option>Two</option></div></select>", body(html));
+        assertEquals(0, errorCount(html));
+    }
+
+    @Test void formattingElementsInSelect() {
+        // option does not generate an implied end for the open b, so nests within it (a parse error)
+        String html = "<select><option><b>One<option>Two</select>";
+        assertEquals("<select><option><b>One<option>Two</option></b></option></select>", body(html));
+        assertTrue(errorCount(html) > 0);
+        // formatting elements are reconstructed before the next option is inserted
+        assertEquals("<select><option><b>One</b></option><b><option>Two</option></b></select>",
+            body("<select><option><b>One</option><option>Two</select>"));
+    }
+
+    @Test void textareaAndKeygenStayInSelect() {
+        assertEquals("<select><textarea>&lt;option&gt;</textarea><keygen></select><p>x</p>",
+            body("<select><textarea><option></textarea><keygen></select><p>x"));
+    }
+
+    @Test void nestedSelectClosesOpenSelect() {
+        String html = "<select><option>A<select><option>B</select>C";
+        assertEquals("<select><option>A</option></select><option>BC</option>", body(html));
+        assertTrue(errorCount(html) > 0);
+    }
+
+    @Test void inputClosesOpenSelect() {
+        assertEquals("<select><option>A</option></select><input>B", body("<select><option>A<input>B"));
+        assertEquals("<select><div><option>A</option></div></select><input>",
+            body("<select><div><option>A<input></div></select>"));
+    }
+
+    @Test void inputInsideTableInSelectDoesNotCloseSelect() {
+        // the table is a scope boundary, so the select is not in scope
+        assertEquals("<select><table><tbody><tr><td><input></td></tr></tbody></table></select>",
+            body("<select><table><tr><td><input></td></tr></table></select>"));
+    }
+
+    @Test void hrInSelectClosesOption() {
+        assertEquals("<select><option>A</option><hr><option>B</option></select>",
+            body("<select><option>A<hr><option>B</select>"));
+        assertEquals("<select><optgroup><option>A</option></optgroup><hr></select>",
+            body("<select><optgroup><option>A<hr></select>"));
+    }
+
+    @Test void optionInSelectClosesOptionButNotOptgroup() {
+        assertEquals("<select><optgroup><option>A</option><option>B</option></optgroup>" +
+                "<optgroup><option>C</option></optgroup></select>",
+            body("<select><optgroup><option>A<option>B<optgroup><option>C</select>"));
+    }
+
+    @Test void optionInSelectClosesImpliedEndTags() {
+        // the option start tag generates implied end tags within the select, so a p is closed
+        assertEquals("<select><option><p>A</p></option><option>B</option></select>",
+            body("<select><option><p>A<option>B</select>"));
+    }
+
+    @Test void optionsOutsideSelect() {
+        assertEquals("<option>A</option><option>B</option><optgroup><option>C</option></optgroup>",
+            body("<option>A<option>B<optgroup><option>C"));
+    }
+
+    @Test void selectEndTagClosesNestedContent() {
+        assertEquals("<select><div><span><option>A</option></span></div></select><p>x</p>",
+            body("<select><div><span><option>A</select><p>x"));
+    }
+
+    @Test void strayEndSelectIgnored() {
+        String html = "<div>A</select>B</div>";
+        assertEquals("<div>AB</div>", body(html));
+        assertTrue(errorCount(html) > 0);
+    }
+
+    @Test void selectInCellClosedByNextCell() {
+        assertEquals("<table><tbody><tr><td><select><option>A</option></select></td><td>B</td></tr></tbody></table>",
+            body("<table><tr><td><select><option>A<td>B</table>"));
+        assertEquals("<table><tbody><tr><td><select><option>A</option></select></td></tr></tbody></table><p>B</p>",
+            body("<table><tr><td><select><option>A</table><p>B"));
+    }
+
+    @Test void selectInTableIsFostered() {
+        assertEquals("<select><option>A</option></select><table><tbody><tr><td>B</td></tr></tbody></table>",
+            body("<table><select><option>A</select><tr><td>B</td></tr></table>"));
+        // table structure tags close the fostered select
+        assertEquals("<select><option>A</option></select><table><tbody><tr><td>B</td></tr></tbody></table>",
+            body("<table><select><option>A<tr><td>B</td></tr></table>"));
+    }
+
+    @Test void selectFragmentContext() {
+        Element context = new Element("select");
+        List<Node> nodes = Parser.parseFragment("<option>A<select><input><option>B</option><optgroup><option>C", context, "");
+        Element holder = new Element("div");
+        holder.appendChildren(nodes);
+        assertEquals("<option>A</option><option>B</option><optgroup><option>C</option></optgroup>",
+            TextUtil.stripNewlines(holder.html()));
+    }
+
+    @Test void selectFragmentViaElementHtml() {
+        Document doc = Jsoup.parse("<select id=s></select>");
+        Element select = doc.expectFirst("#s");
+        select.html("<option>One<select><option>Two<input>");
+        assertEquals("<option>One</option><option>Two</option>", TextUtil.stripNewlines(select.html()));
+    }
+}

